public class SearchInRotatedSortedArray {
    public int search(int[] nums, int target) {
        int left = 0, right = nums.length - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;  // 防溢出

            if (nums[mid] == target) {
                return mid;                        // 命中直接返回
            }

            if (nums[left] <= nums[mid]) {
                // 左半有序: [left, mid] 递增
                if (nums[left] <= target && target < nums[mid]) {
                    right = mid - 1;               // target 在有序左半
                } else {
                    left = mid + 1;                // target 在无序右半
                }
            } else {
                // 右半有序: [mid, right] 递增
                if (nums[mid] < target && target <= nums[right]) {
                    left = mid + 1;                // target 在有序右半
                } else {
                    right = mid - 1;               // target 在无序左半
                }
            }
        }

        return -1;  // 未找到
    }

    // 有重复元素版本 (LeetCode 81)
    public boolean searchWithDuplicates(int[] nums, int target) {
        int left = 0, right = nums.length - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (nums[mid] == target) return true;

            // 歧义情况：三者相等，无法判断哪半有序
            if (nums[left] == nums[mid] && nums[mid] == nums[right]) {
                left++;
                right--;
            } else if (nums[left] <= nums[mid]) {
                if (nums[left] <= target && target < nums[mid]) {
                    right = mid - 1;
                } else {
                    left = mid + 1;
                }
            } else {
                if (nums[mid] < target && target <= nums[right]) {
                    left = mid - 1;
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
        }

        return false;
    }

    public static void main(String[] args) {
        SearchInRotatedSortedArray s = new SearchInRotatedSortedArray();
        System.out.println(s.search(new int[]{4,5,6,7,0,1,2}, 0)); // 4
        System.out.println(s.search(new int[]{4,5,6,7,0,1,2}, 3)); // -1
        System.out.println(s.search(new int[]{1}, 0));             // -1
        System.out.println(s.search(new int[]{1}, 1));             // 0
        System.out.println(s.search(new int[]{3,1}, 1));           // 1
    }
}
